const SCATTERED_IMGS = [imgHeroMobile, imgHeroPweb, imgHeroPweb3, imgHeroVcshow];

/* ── Hero Lightbox ────────────────────────────────────── */

/* ── Scattered Frames ── */
function ScatteredFrames({ onOpenLightbox }) {
  return (
    <div className="hero-scatter">
      {SCATTERED_IMGS.map((src, i) => (
        <button
          key={i}
          className={`hero-scatter__card hero-scatter__card--${i}`}
          onClick={() => onOpenLightbox(SCATTERED_IMGS, i)}
          aria-label={`View screenshot ${i + 1} full screen`}
        >
          <div className="hero-scatter__topbar">
            <span /><span /><span />
          </div>
          <div className="hero-scatter__img-wrap">
            <img src={src} alt="" className="hero-scatter__img" />
            <div className="hero-scatter__overlay">
              <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2">
                <path strokeLinecap="round" strokeLinejoin="round" d="M15 3h6m0 0v6m0-6L14 10M9 21H3m0 0v-6m0 6l7-7" />
              </svg>
            </div>
          </div>
        </button>
      ))}
    </div>
  );
}

/* ── Sun and Clouds Background Animation ── */
function SunCloudsAnimation() {
  return (
    <div className="sun-clouds-container">
      <div className="cloud front">
        <span className="left-front"></span>
        <span className="right-front"></span>
      </div>
      <span className="sun sunshine"></span>
      <span className="sun"></span>
      <div className="cloud back">
        <span className="left-back"></span>
        <span className="right-back"></span>
      </div>
    </div>
  );
}

